(()=>{'use strict';const game=['/game','/game/','/index.html'].includes(location.pathname),audio=new Audio('/assets/media/vesper-desert-score.mp3?v=0.97.0');audio.hidden=true;audio.preload='none';document.body.append(audio);audio.loop=true;audio.volume=.22;let enabled=!game,toolbar,videoPlaying=false;try{if(!game)enabled=localStorage.getItem('starfall-portal-music-enabled')!=='false';}catch{}
function wanted(){return game?typeof state!=='undefined'&&!!state.userSettings.gameAmbientMusic:enabled;}
function status(message){const el=document.getElementById(game?'gameMusicStatus':'portalMusicStatus');if(el)el.textContent=message;const button=document.getElementById('portalMusicToggle');if(button){button.textContent=wanted()?'MUTE MUSIC':'ENABLE MUSIC';button.setAttribute('aria-pressed',String(wanted()));}}
async function apply(){if(!wanted()||videoPlaying){audio.pause();status(!wanted()?'Music off':'Music paused while video plays');return;}try{await audio.play();status('Vesper desert score · playing');}catch{status('Music ready · starts after your next click');}}
window.applyAmbientMusic=apply;
if(!game){toolbar=document.createElement('div');toolbar.className='portal-music-toolbar';toolbar.innerHTML='<span id="portalMusicStatus" role="status">Original cinematic ambience</span><button id="portalMusicToggle" class="button secondary" type="button">MUTE MUSIC</button><label for="portalMusicVolume">Volume <input id="portalMusicVolume" type="range" min="0" max="100" value="22"></label>';const settings=document.querySelector('.profile-theme-section');if(settings){toolbar.classList.add('profile-theme-box');settings.append(toolbar);}else{toolbar.hidden=true;document.body.append(toolbar);}document.getElementById('portalMusicToggle').addEventListener('click',()=>{enabled=!enabled;try{localStorage.setItem('starfall-portal-music-enabled',String(enabled));}catch{}apply();});document.getElementById('portalMusicVolume').addEventListener('input',e=>audio.volume=Number(e.target.value)/100);}
document.addEventListener('pointerdown',()=>{if(wanted()&&audio.paused&&!videoPlaying)apply();});document.addEventListener('keydown',()=>{if(wanted()&&audio.paused&&!videoPlaying)apply();});document.addEventListener('play',e=>{if(e.target.tagName==='VIDEO'){videoPlaying=true;apply();}},true);for(const event of ['pause','ended'])document.addEventListener(event,e=>{if(e.target.tagName==='VIDEO'){videoPlaying=[...document.querySelectorAll('video')].some(v=>!v.paused&&!v.ended);apply();}},true);document.addEventListener('visibilitychange',()=>{if(document.hidden)audio.pause();else apply();});apply();})();
